import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

/** No outer rollback transaction: fixtures and each real JWT MockMvc call commit independently.
 * Named PostgreSQL blockers establish actual waits, not a timing-only thread race.
 * The scope holder uses the original authenticated ADMIN controller before starting
 * its waiter, within the holder's real transaction. SQL row locks are test barriers;
 * employee changes use the public system API, not direct SQL business mutations. */
@SpringBootTest @AutoConfigureMockMvc
class V144EmrTemplateWriteAccessTest {
    @Autowired JdbcTemplate jdbc;
    @Autowired MockMvc mvc;
    @Autowired JwtService jwt;
    @Autowired ObjectMapper mapper;
    @Autowired PlatformTransactionManager manager;
    @Autowired MedTechController templates;
    @Autowired EntityManager em;
    record Staff(Long id,String name,String token) {}
    record Reply(int http,JsonNode body) { int code(){return body.path("code").asInt();} }
    record Audit(String method,String path,int status,String username) {}
    static final List<String> DUTIES=List.of("ADMIN","DOCTOR_OUTP","NURSE","QUALITY","TECHNICIAN");
    static final List<String> OPS=List.of("update","disable","enable","grant","revoke","default","replace","unset");
    String tag; Long dept,foreignDept,template,otherTemplate,grantId; Staff actor,owner,admin,viewer;
    final List<Staff> people=new ArrayList<>();
    @BeforeEach void setup(){
        SecurityContextHolder.clearContext();tag="V144T"+Long.toUnsignedString(System.nanoTime(),36);
        dept=jdbc.queryForObject("insert into sys_dept(code,name,type) values (?,?,'CLINICAL') returning id",Long.class,tag+"D",tag+"本科");
        foreignDept=jdbc.queryForObject("insert into sys_dept(code,name,type) values (?,?,'CLINICAL') returning id",Long.class,tag+"X",tag+"他科");
        actor=employee("actor","DOCTOR_OUTP",dept);owner=employee("owner","DOCTOR_OUTP",dept);
        admin=employee("admin","ADMIN",dept);viewer=employee("viewer","DOCTOR_OUTP",foreignDept);
        template=newTemplate("T",owner.id());otherTemplate=newTemplate("X",owner.id());configure("DEPT",false);
    }
    Staff employee(String suffix,String duty,Long department){String name=tag+suffix;Long id=jdbc.queryForObject("insert into sys_user(username,password,real_name,dept_id,enabled) values (?,'x',?,?,true) returning id",Long.class,name,name,department);var s=new Staff(id,name,jwt.issue(name));people.add(s);roles(s,duty);return s;}
    void roles(Staff s,String... duties){jdbc.update("delete from sys_user_role where user_id=?",s.id());for(String duty:duties)assertEquals(1,jdbc.update("insert into sys_user_role(user_id,role_id) select ?,id from sys_role where code=?",s.id(),duty));}
    Long newTemplate(String suffix,Long who){return jdbc.queryForObject("insert into emr_template(dept_id,name,content,template_type,scope,owner_id,record_type,enabled,created_by) values (?,?,?,'EMR','DEPT',?,'PROGRESS',true,?) returning id",Long.class,dept,tag+suffix,"原正文",who,who);}
    Long grant(Long t,String type,Long who){return jdbc.queryForObject("insert into emr_template_grant(template_id,grantee_type,grantee_id,granted_by) values (?,?,?,?) returning id",Long.class,t,type,who,admin.id());}
    void configure(String scope,boolean own){jdbc.update("update emr_template set is_default=false,enabled=true,scope=?,owner_id=?,dept_id=? where id=?",scope,own?actor.id():owner.id(),scope.equals("DEPT")?dept:null,template);jdbc.update("update emr_template set is_default=false,enabled=true,dept_id=?,record_type='PROGRESS' where id=?",dept,otherTemplate);jdbc.update("delete from emr_template_grant where template_id=?",template);if(scope.equals("DEPT"))grant(template,"DEPT",dept);if(scope.equals("PERSONAL"))grant(template,"USER",own?actor.id():owner.id());grantId=grant(template,"USER",viewer.id());}
    void prepare(String op){if(op.equals("enable"))jdbc.update("update emr_template set enabled=false where id=?",template);if(op.equals("unset"))jdbc.update("update emr_template set is_default=true where id=?",template);}
    String path(String op){String base="/api/emr-templates/"+template;return switch(op){case "update"->base;case "grant"->base+"/grants";case "revoke"->base+"/grants/"+grantId;case "default","unset"->base+"/default";case "replace"->base+"/default?replace=true";default->base+"/"+op;};}
    String method(String op){return switch(op){case "grant"->"POST";case "revoke","unset"->"DELETE";default->"PUT";};}
    Object body(String op){return switch(op){case "update"->Map.of("name",tag+"改","content","新正文","templateType","EMR","deptId",dept,"recordType","PROGRESS");case "grant"->Map.of("granteeType","USER","granteeId",admin.id());default->null;};}
    Reply call(String method,String path,Object body,String token)throws Exception{SecurityContextHolder.clearContext();try{MockHttpServletRequestBuilder req=switch(method){case "POST"->post(path);case "PUT"->put(path);case "DELETE"->delete(path);default->get(path);};if(body!=null)req.contentType("application/json").content(mapper.writeValueAsString(body));if(token!=null)req.header("Authorization","Bearer "+token);var response=mvc.perform(req).andReturn().getResponse();return new Reply(response.getStatus(),mapper.readTree(response.getContentAsString(StandardCharsets.UTF_8)));}finally{SecurityContextHolder.clearContext();}}
    Reply request(String op)throws Exception{return call(method(op),path(op),body(op),actor.token());}
    Map<String,List<Map<String,Object>>> facts(){var result=new LinkedHashMap<String,List<Map<String,Object>>>();result.put("templates",jdbc.queryForList("select * from emr_template where id in (?,?) order by id",template,otherTemplate));result.put("fields",jdbc.queryForList("select * from emr_template_field where template_id in (?,?) order by id",template,otherTemplate));result.put("grants",jdbc.queryForList("select * from emr_template_grant where template_id in (?,?) order by id",template,otherTemplate));for(String table:List.of("empi_patient","outp_registration","outp_order","outp_charge","outp_emr","inp_admission","inp_order","inp_medical_record","lis_sample","lab_micro_result","lab_micro_ast","ris_exam","path_specimen","path_process","emr_consent","cdr_document","fin_print_log"))result.put(table,jdbc.queryForList("select * from "+table+" order by id"));result.put("config",jdbc.queryForList("select * from sys_config order by cfg_key"));return result;}
    Map<String,List<Map<String,Object>>> copy(Map<String,List<Map<String,Object>>> source){var result=new LinkedHashMap<String,List<Map<String,Object>>>();source.forEach((k,v)->{var rows=new ArrayList<Map<String,Object>>();for(var row:v)rows.add(new LinkedHashMap<>(row));result.put(k,rows);});return result;}
    Map<String,Object> row(Map<String,List<Map<String,Object>>> f,String key,Long id){return f.get(key).stream().filter(r->id.equals(r.get("id"))).findFirst().orElseThrow();}
    List<Map<String,Object>> authFacts(){return jdbc.queryForList("select to_jsonb(u)::text as employee,coalesce((select jsonb_agg(to_jsonb(ur) order by ur.role_id) from sys_user_role ur where ur.user_id=u.id),'[]'::jsonb)::text as roles from sys_user u where username like ? order by id",tag+"%");}
    List<Map<String,Object>> audit(){return jdbc.queryForList("select * from sys_audit_log order by id");}
    void audited(List<Map<String,Object>> before,Audit... expected){var all=audit();var old=new HashMap<Object,Map<String,Object>>();before.forEach(r->old.put(r.get("id"),r));var fresh=new ArrayList<Map<String,Object>>();for(var r:all){if(old.containsKey(r.get("id")))assertEquals(old.remove(r.get("id")),r);else fresh.add(r);}assertTrue(old.isEmpty());assertEquals(expected.length,fresh.size(),fresh.toString());for(int i=0;i<expected.length;i++){var r=fresh.get(i);var e=expected[i];assertEquals(Set.of("id","username","method","path","http_status","client_ip","created_at"),r.keySet());assertEquals(e.method(),r.get("method"));assertTrue(r.get("path").toString().startsWith(e.path()));assertEquals(e.status(),((Number)r.get("http_status")).intValue());assertEquals(e.username(),r.get("username"));assertEquals("127.0.0.1",r.get("client_ip"));}}
    void code(Reply r,int status,int value){var keys=new HashSet<String>();r.body().fieldNames().forEachRemaining(keys::add);assertEquals(Set.of("code","message","data"),keys);assertAll(()->assertEquals(status,r.http(),r.body().toString()),()->assertEquals(value,r.code(),r.body().toString()));assertTrue(r.body().path("data").isNull());}
    Instant clock(){return jdbc.queryForObject("select clock_timestamp()",Timestamp.class).toInstant();}
    void accepted(String op,Reply r,Map<String,List<Map<String,Object>>> before,Instant lower){code(r,200,0);var actual=facts();var expected=copy(before);var t=row(expected,"templates",template);switch(op){case "update"->{t.put("name",tag+"改");t.put("content","新正文");}case "enable","disable"->t.put("enabled",op.equals("enable"));case "default","replace"->t.put("is_default",true);case "unset"->t.put("is_default",false);case "revoke"->assertTrue(expected.get("grants").removeIf(g->grantId.equals(g.get("id"))));case "grant"->{var oldIds=before.get("grants").stream().map(g->g.get("id")).toList();var added=actual.get("grants").stream().filter(g->!oldIds.contains(g.get("id"))).toList();assertEquals(1,added.size());var g=added.getFirst();Timestamp at=(Timestamp)g.get("granted_at");assertFalse(at.toInstant().isBefore(lower));assertFalse(at.toInstant().isAfter(clock()));assertEquals(Map.of("id",g.get("id"),"template_id",template,"grantee_type","USER","grantee_id",admin.id(),"granted_by",actor.id(),"granted_at",at),g);expected.get("grants").add(new LinkedHashMap<>(g));expected.get("grants").sort(Comparator.comparingLong(x->((Number)x.get("id")).longValue()));}default->fail(op);}assertEquals(expected,actual,"Only the authorized header/grant columns may change");}
    static Stream<Arguments> matrix(){return Stream.of("GLOBAL","HOSPITAL","DEPT","PERSONAL").flatMap(scope->DUTIES.stream().map(duty->Arguments.of(scope,duty)));}
    @ParameterizedTest @MethodSource("matrix") void originalFiveDutiesKeepTheFourScopeMaintenanceMatrix(String scope,String duty)throws Exception{configure(scope,false);roles(actor,duty);boolean allowed=!scope.equals("PERSONAL")&&duty.equals("ADMIN");for(String op:List.of("update","disable","enable","grant","revoke")){prepare(op);var before=facts();var auth=authFacts();var audits=audit();Instant lower=clock();var reply=request(op);if(allowed)accepted(op,reply,before,lower);else{code(reply,200,4066);assertEquals(before,facts());}assertEquals(auth,authFacts());audited(audits,new Audit(method(op),path(op),200,actor.name()));}}
    @ParameterizedTest @CsvSource({"DEPT,ADMIN","DEPT,DOCTOR_OUTP","DEPT,NURSE","DEPT,QUALITY","DEPT,TECHNICIAN","PERSONAL,ADMIN","PERSONAL,DOCTOR_OUTP","PERSONAL,NURSE","PERSONAL,QUALITY","PERSONAL,TECHNICIAN"}) void eachOriginalDutyCanMaintainItsOwnPrivateOrDepartmentTemplate(String scope,String duty)throws Exception{configure(scope,true);roles(actor,duty);for(String op:scope.equals("DEPT")?OPS:List.of("update","disable","enable","grant","revoke","unset")){prepare(op);var before=facts();Instant lower=clock();accepted(op,request(op),before,lower);}}
    @ParameterizedTest @ValueSource(strings={"USER","DEPT"}) void grantsNeverConferMaintenance(String type)throws Exception{configure("PERSONAL",false);grant(template,type,type.equals("USER")?actor.id():dept);var before=facts();for(String op:OPS){code(request(op),200,4066);assertEquals(before,facts());}}
    @ParameterizedTest @CsvSource({"CASHIER,403,1005","INTERFACE,403,1005","anonymous,401,1000","disabled,401,1000"}) void originalEntryDenialsRemainBusinessSafe(String who,int http,int value)throws Exception{configure("PERSONAL",true);String token=actor.token();if(who.equals("anonymous"))token=null;else if(who.equals("disabled"))jdbc.update("update sys_user set enabled=false where id=?",actor.id());else roles(actor,who);var before=facts();for(String op:OPS){code(call(method(op),path(op),body(op),token),http,value);assertEquals(before,facts());}}
    @ParameterizedTest @ValueSource(strings={"update","enable","disable","grant","revoke","default","replace","unset"}) void missingTargetAndInvisibleTargetShare4066(String op)throws Exception{configure("PERSONAL",true);Long saved=template;template=899999999999999L;String endpoint=path(op);template=saved;var before=facts();code(call(method(op),endpoint,body(op),actor.token()),200,4066);assertEquals(before,facts());}
    TransactionTemplate tx(){var t=new TransactionTemplate(manager);t.setTimeout(30);return t;}
    void lockT(Long id){assertEquals(1,jdbc.queryForList("select id from emr_template where id=? for update",id).size());}
    void lockGrants(){jdbc.queryForList("select id from emr_template_grant where template_id=? for update",template);}
    void awaitHolder(int holder,List<? extends Future<?>> workers){long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(12);while(System.nanoTime()<end){jdbc.execute("select pg_stat_clear_snapshot()");var waits=jdbc.queryForList("select pid,pg_blocking_pids(pid)::text as blockers,query,wait_event from pg_stat_activity where datname=current_database() and pid<>pg_backend_pid() and wait_event_type='Lock' and (lower(query) like '%emr_template%' or lower(query) like '%pg_advisory%')");var reachable=new HashSet<Integer>();reachable.add(holder);boolean changed;do{changed=false;for(var r:waits)for(Integer pid:List.copyOf(reachable))if(Arrays.asList(r.get("blockers").toString().replace("{","").replace("}","").split(",")).contains(pid.toString()))changed|=reachable.add(((Number)r.get("pid")).intValue());}while(changed);long count=waits.stream().filter(r->reachable.contains(((Number)r.get("pid")).intValue())).count();if(count>=workers.size()){System.out.println("V144 PG_LOCK holder="+holder+" requestCount="+workers.size()+" waits="+waits);return;}if(workers.stream().anyMatch(Future::isDone))fail("Request completed without the named holder PostgreSQL wait");try{Thread.sleep(15);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new RuntimeException(e);}}fail("No exact named-holder PostgreSQL wait graph");}
    Reply finish(Future<Reply> worker)throws Exception{try{return worker.get(20,TimeUnit.SECONDS);}catch(ExecutionException e){return fail("Unexpected request/fixture exception",e.getCause());}}
    void close(ExecutorService pool)throws Exception{pool.shutdownNow();assertTrue(pool.awaitTermination(10,TimeUnit.SECONDS));}
    void publicScope(String scope){var auth=new UsernamePasswordAuthenticationToken(admin.name(),null,List.of(new SimpleGrantedAuthority("ROLE_ADMIN")));SecurityContextHolder.getContext().setAuthentication(auth);try{assertEquals(0,templates.updateTemplate(template,new EmrTemplateService.TemplateReq(tag+"T","原正文","EMR",scope,scope.equals("DEPT")?dept:null,"PROGRESS"),auth).getCode());}finally{SecurityContextHolder.clearContext();}}
    static Stream<Arguments> scopeWait(){return OPS.stream().flatMap(op->Stream.of("HOSPITAL","PERSONAL").map(scope->Arguments.of(op,scope)));}
    @ParameterizedTest @MethodSource("scopeWait") void committedPublicScopeChangeRevokesTheWaitingMaintenance(String op,String scope)throws Exception{configure("DEPT",scope.equals("HOSPITAL"));roles(actor,scope.equals("PERSONAL")?"ADMIN":"DOCTOR_OUTP");prepare(op);var pool=Executors.newSingleThreadExecutor();var future=new AtomicReference<Future<Reply>>();var expected=new AtomicReference<Map<String,List<Map<String,Object>>>>();var audits=audit();try{tx().executeWithoutResult(s->{publicScope(scope);lockT(template);int holder=jdbc.queryForObject("select pg_backend_pid()",Integer.class);future.set(pool.submit(()->request(op)));awaitHolder(holder,List.of(future.get()));expected.set(facts());});var reply=finish(future.get());System.out.println("V144 SCOPE op="+op+" new="+scope+" actual="+reply.http()+"/"+reply.code());code(reply,200,4066);assertEquals(expected.get(),facts());audited(audits,new Audit(method(op),path(op),200,actor.name()));}finally{close(pool);}}
    @ParameterizedTest @ValueSource(strings={"update","disable","enable","grant","revoke","default","replace","unset"}) void rollbackOfPublicScopeChangeRetainsTheOriginalOwnerEligibility(String op)throws Exception{configure("DEPT",true);prepare(op);var before=facts();var pool=Executors.newSingleThreadExecutor();var future=new AtomicReference<Future<Reply>>();Instant lower=clock();try{tx().executeWithoutResult(s->{publicScope("HOSPITAL");lockT(template);int holder=jdbc.queryForObject("select pg_backend_pid()",Integer.class);future.set(pool.submit(()->request(op)));awaitHolder(holder,List.of(future.get()));s.setRollbackOnly();});accepted(op,finish(future.get()),before,lower);}finally{close(pool);}}
    void publicEmployee(String change){try{String endpoint="/api/system/users/"+actor.id();Reply reply=change.equals("disabled")?call("PUT",endpoint+"/enabled?enabled=false",null,admin.token()):call("PUT",endpoint,Map.of("username",actor.name(),"realName",actor.name(),"deptId",dept,"roleCodes",change.equals("NO_ROLES")?List.of():List.of(change)),admin.token());code(reply,200,0);em.flush();em.clear();}catch(Exception e){throw new RuntimeException(e);}}
    static Stream<Arguments> dutyWait(){return OPS.stream().flatMap(op->Stream.of("TECHNICIAN","QUALITY","CASHIER","NO_ROLES","disabled").map(change->Arguments.of(op,change)));}
    @ParameterizedTest @MethodSource("dutyWait") void committedPublicEmployeeChangeAfterNamedTargetWaitUsesFreshDuties(String op,String change)throws Exception{configure("DEPT",false);roles(actor,"ADMIN");prepare(op);var before=facts();var pool=Executors.newSingleThreadExecutor();var future=new AtomicReference<Future<Reply>>();var changedAuth=new AtomicReference<List<Map<String,Object>>>();var audits=audit();try{tx().executeWithoutResult(s->{lockT(template);lockGrants();int holder=jdbc.queryForObject("select pg_backend_pid()",Integer.class);future.set(pool.submit(()->request(op)));awaitHolder(holder,List.of(future.get()));publicEmployee(change);changedAuth.set(authFacts());});var reply=finish(future.get());boolean denied=Set.of("CASHIER","NO_ROLES","disabled").contains(change);int value=denied?1005:4066;System.out.println("V144 DUTY op="+op+" change="+change+" actual="+reply.http()+"/"+reply.code());code(reply,denied?403:200,value);assertEquals(before,facts());assertEquals(changedAuth.get(),authFacts());audited(audits,new Audit("PUT","/api/system/users/"+actor.id(),200,admin.name()),new Audit(method(op),path(op),denied?403:200,actor.name()));}finally{close(pool);}}
    @ParameterizedTest @ValueSource(strings={"TECHNICIAN","NURSE","QUALITY","ADMIN"}) void ownerTransferredWithinOriginalDutiesStillMaintainsTheSameTemplate(String duty)throws Exception{configure("PERSONAL",true);var before=facts();var pool=Executors.newSingleThreadExecutor();var future=new AtomicReference<Future<Reply>>();Instant lower=clock();try{tx().executeWithoutResult(s->{lockT(template);int holder=jdbc.queryForObject("select pg_backend_pid()",Integer.class);future.set(pool.submit(()->request("update")));awaitHolder(holder,List.of(future.get()));publicEmployee(duty);});accepted("update",finish(future.get()),before,lower);}finally{close(pool);}}
    @ParameterizedTest @ValueSource(strings={"TECHNICIAN","CASHIER","disabled"}) void defaultReplacementRechecksAfterTheOtherDefaultRowWait(String change)throws Exception{configure("DEPT",false);roles(actor,"ADMIN");jdbc.update("update emr_template set is_default=true where id=?",otherTemplate);var before=facts();var pool=Executors.newSingleThreadExecutor();var future=new AtomicReference<Future<Reply>>();try{tx().executeWithoutResult(s->{lockT(otherTemplate);int holder=jdbc.queryForObject("select pg_backend_pid()",Integer.class);future.set(pool.submit(()->request("replace")));awaitHolder(holder,List.of(future.get()));publicEmployee(change);});var reply=finish(future.get());code(reply,change.equals("TECHNICIAN")?200:403,change.equals("TECHNICIAN")?4066:1005);assertEquals(before,facts(),"Neither default may change after duty loss during the second template wait");}finally{close(pool);}}
    @ParameterizedTest @ValueSource(strings={"TECHNICIAN","CASHIER","disabled"}) void revokeRechecksAfterTheGrantRowWait(String change)throws Exception{configure("DEPT",false);roles(actor,"ADMIN");var before=facts();var pool=Executors.newSingleThreadExecutor();var future=new AtomicReference<Future<Reply>>();try{tx().executeWithoutResult(s->{lockGrants();int holder=jdbc.queryForObject("select pg_backend_pid()",Integer.class);future.set(pool.submit(()->request("revoke")));awaitHolder(holder,List.of(future.get()));publicEmployee(change);});code(finish(future.get()),change.equals("TECHNICIAN")?200:403,change.equals("TECHNICIAN")?4066:1005);assertEquals(before,facts());}finally{close(pool);}}
    @Test void sameTargetConcurrentDefaultReplacementReturnsReadableResultsAndExactlyOneDefault()throws Exception{configure("DEPT",true);jdbc.update("update emr_template set is_default=true where id=?",otherTemplate);var pool=Executors.newFixedThreadPool(2);var futures=new ArrayList<Future<Reply>>();try{tx().executeWithoutResult(s->{lockT(otherTemplate);int holder=jdbc.queryForObject("select pg_backend_pid()",Integer.class);for(int i=0;i<2;i++)futures.add(pool.submit(()->request("replace")));awaitHolder(holder,futures);});var replies=new ArrayList<Reply>();for(var f:futures)replies.add(finish(f));assertEquals(2,replies.stream().filter(r->r.http()==200&&r.code()==0).count());assertEquals(0,replies.stream().filter(r->r.code()!=0).count());var after=facts();assertEquals(1,after.get("templates").stream().filter(t->Boolean.TRUE.equals(t.get("enabled"))&&Boolean.TRUE.equals(t.get("is_default"))).count());assertEquals(true,row(after,"templates",template).get("is_default"));assertEquals(false,row(after,"templates",otherTemplate).get("is_default"));}finally{close(pool);}}
    @Test void disabledTemplatesRemainMaintainableAndDefaultErrorsStay4067()throws Exception{configure("DEPT",true);jdbc.update("update emr_template set enabled=false where id=?",template);var before=facts();Instant lower=clock();accepted("update",request("update"),before,lower);before=facts();code(request("default"),200,4067);assertEquals(before,facts());accepted("enable",request("enable"),before,clock());}
    @Test void foreignGrantIdsAndOwnAutomaticGrantKeep4065()throws Exception{configure("DEPT",true);var before=facts();Long original=grantId;grantId=grant(otherTemplate,"USER",viewer.id());var withOther=facts();code(request("revoke"),200,4065);assertEquals(withOther,facts());grantId=jdbc.queryForObject("select id from emr_template_grant where template_id=? and grantee_type='DEPT' and grantee_id=?",Long.class,template,dept);code(request("revoke"),200,4065);assertEquals(withOther,facts());grantId=original;assertEquals(before.get("templates"),facts().get("templates"));}
    @AfterEach void cleanup(){SecurityContextHolder.clearContext();if(template!=null){jdbc.update("delete from emr_template_field where template_id in (?,?)",template,otherTemplate);jdbc.update("delete from emr_template_grant where template_id in (?,?)",template,otherTemplate);jdbc.update("delete from emr_template where id in (?,?)",template,otherTemplate);}for(var who:people){jdbc.update("delete from sys_user_role where user_id=?",who.id());jdbc.update("delete from sys_user where id=?",who.id());}if(dept!=null)jdbc.update("delete from sys_dept where id in (?,?)",dept,foreignDept);people.clear();}
}
